121	bool MergeTreeIndexConditionText::requiresReadingAllTokens(const RPNElement & element)
122	{
123	    switch (element.function)
124	    {
125	        case RPNElement::FUNCTION_OR:
126	        case RPNElement::FUNCTION_NOT:
127	        case RPNElement::FUNCTION_NOT_IN:
128	        case RPNElement::FUNCTION_NOT_EQUALS:
129	        case RPNElement::FUNCTION_HAS_ANY_TOKENS:
130	        {
131	            return true;
132	        }
133	        case RPNElement::FUNCTION_AND:
134	        case RPNElement::FUNCTION_EQUALS:
135	        case RPNElement::FUNCTION_HAS_ALL_TOKENS:
136	        case RPNElement::FUNCTION_UNKNOWN:
137	        case RPNElement::ALWAYS_TRUE:
138	        case RPNElement::ALWAYS_FALSE:
139	        {
140	            return false;
141	        }
142	        case RPNElement::FUNCTION_IN:
143	        case RPNElement::FUNCTION_MATCH:
144	        {
145	            return element.text_search_queries.size() != 1;
146	        }
147	    }
148	}
