    /// with an index defined on `mapValues(map)` (search for the values, like `traverseMapElementValueNode`)
    /// or on `mapKeys(map)` (search for the constant key, like `traverseMapElementKeyNode`).
    if (!node.isFunction())
        return SetKeyMatch::None;

    const auto function = node.toFunctionNode();
    if (function.getFunctionName() != "arrayElement" || function.getArgumentsSize() != 2)
        return SetKeyMatch::None;

    Field key_field;
    DataTypePtr key_type;
    if (!function.getArgumentAt(1).tryGetConstant(key_field, key_type))
        return SetKeyMatch::None;

    if (key_field.getType() != Field::Types::String)
        return SetKeyMatch::None;

    const auto map_column_name = function.getArgumentAt(0).getColumnName();

    if (header.has(fmt::format("mapValues({})", map_column_name)))
        return SetKeyMatch::MapValues;

    if (header.has(fmt::format("mapKeys({})", map_column_name)))
    {
        out_map_key = key_field.safeGet<String>();
        return SetKeyMatch::MapKeys;
    }

    return SetKeyMatch::None;
