    const RPNBuilderTreeNode & lhs,
    const RPNBuilderTreeNode & rhs,
    const String & function_name,
    RPNElement & out) const
{
    std::optional<size_t> set_key_position;
    SetKeyMatch set_key_match = SetKeyMatch::None;
    String map_keys_search_key;

    /// Records a match at `position` if `node` refers to this index's column.
    /// Returns false if a second index column is matched (text index supports only one).
    auto consider = [&](const RPNBuilderTreeNode & node, size_t position) -> bool
    {
        String map_key;
        auto match = matchSetKeyColumn(node, map_key);
        if (match == SetKeyMatch::None)
            return true;

        if (set_key_position.has_value())
            return false;

        set_key_position = position;
        set_key_match = match;
        map_keys_search_key = std::move(map_key);
        return true;
    };

    if (lhs.isFunction() && lhs.toFunctionNode().getFunctionName() == "tuple")
    {
        const auto function = lhs.toFunctionNode();
        auto arguments_size = function.getArgumentsSize();

        for (size_t i = 0; i < arguments_size; ++i)
        {
            if (!consider(function.getArgumentAt(i), i))
                return false;
        }
    }
    else
    {
        if (!consider(lhs, 0))
            return false;
    }

    if (!set_key_position.has_value())
        return false;

    bool matched_map_element = set_key_match == SetKeyMatch::MapValues || set_key_match == SetKeyMatch::MapKeys;

    /// `map[key]` returns the default value (empty string) when the key is absent, so a granule
    /// without the key can still satisfy the condition. We only support the positive `IN` for such
    /// expressions, where a missing empty string among the values guarantees the key is present.
    if (matched_map_element && function_name != "in")
        return false;

    auto future_set = rhs.tryGetPreparedSet();
    if (!future_set)
        return false;

    auto prepared_set = future_set->buildOrderedSetInplace(rhs.getTreeContext().getQueryContext());
    if (!prepared_set || !prepared_set->hasExplicitSetElements())
        return false;

    Columns columns = prepared_set->getSetElements();
    const auto & set_column = *columns[*set_key_position];

    if (!WhichDataType(set_column.getDataType()).isStringOrFixedString())
        return false;

    size_t total_row_count = prepared_set->getTotalRowCount();

    if (matched_map_element)
    {
